			function doList() {
			    
			    util.Submit.send(app, "subList", function(pbSuccess) {
			        if (pbSuccess) {
			            // doList();
			            var dmDetail = app.lookup("dmDetail");
			            var dsList = app.lookup("dsList");
			            dsList.setRowStateAll(cpr.data.tabledata.RowState.UNCHANGED);
			            var cmnsinglefileupload1 = app.lookup("cmnsinglefileuploadweb1");
			            var cmnsinglefileupload2 = app.lookup("cmnsinglefileuploadweb1");
			            
			            
			            cmnsinglefileupload1.setBindContext(new cpr.bind.DataRowContext(dsList, 0));
			            cmnsinglefileupload2.setBindContext(new cpr.bind.DataRowContext(dsList, 1));
			            
			            setImageInfo();
			            var grp2 = app.lookup("grp2");
			            if ("3" == dmDetail.getValue("APRV_STTS_SE_CD")) {
			                util.Control.setVisible(app, false, ["btnSave", "btnClose2"]); // 저장, 취소
			                util.Control.setVisible(app, true, ["opt6", "ipb9"]); // 반려사유 노출
			                grp2.getLayout().setRowVisible(15, true);
			                  
			            } else {
			                util.Control.setVisible(app, true, ["btnSave", "btnClose2"]); // 저장, 취소
			                util.Control.setVisible(app, false, ["opt6", "ipb9"]); // 반려사유 노출
			                grp2.getLayout().setRowVisible(15, false);
			            }
			            app.lookup("grp2").redraw();
			            app.lookup("grp1").redraw();
			        }
			    });
			}

